import { useState } from "react";

function Profile() {

  const [books] = useState([
    { title: "데미안", content: "자아를 찾아가는 이야기" },
    { title: "1984", content: "감시 사회에 대한 경고" },
    { title: "소년이 온다", content: "역사의 아픔" }
  ]);

  return (
    <div style={{ padding: "15px" }}>
      
      <h3 style={{ color: "#4CAF50" }}>MY BOOKSHELF</h3>

      {/* 프로필 */}
      <div style={{
        display: "flex",
        gap: "10px",
        alignItems: "center",
        marginBottom: "20px"
      }}>
        <div style={{
          width: "50px",
          height: "50px",
          borderRadius: "50%",
          background: "#7ED957"
        }} />

        <div>
          <div><b>READLY USER</b></div>
          <div style={{ fontSize: "12px", color: "#888" }}>
            내 독서 기록
          </div>
        </div>
      </div>

      {/* 책장 */}
      <div style={{
        display: "flex",
        flexDirection: "column",
        gap: "10px"
      }}>
        {books.map((book, i) => (
          <div key={i} style={bookCard}>
            📘 {book.title}
          </div>
        ))}
      </div>

    </div>
  );
}

const bookCard = {
  background: "white",
  padding: "15px",
  borderRadius: "12px",
  borderLeft: "5px solid #7ED957",
  cursor: "pointer"
};

export default Profile;
